#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    Create,
    Drop,
    DbDrop,
    StageCreate,
    Bind,
    Recreate,
    /// something of the collection stamped at `hlc`: a write, a delete or a definition
    Touch,
    /// unused until unit 16 (`AbandonStage`): a stage's creator withdraws it
    Abandon,
}

#[derive(Clone, Copy, Debug)]
pub struct Fact {
    pub kind: Kind,
    pub origin: usize,
    pub hlc: u64,
    pub name: &'static str,
    pub deadline: u64,
    /// a `Drop` that is a database drop's own entry of the collection: the hlc of that database drop
    pub db_entry: Option<u64>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Served {
    Absent,
    Identity,
    Stage(&'static str),
    Recreation(&'static str),
}

pub struct Case {
    pub tag: &'static str,
    pub facts: &'static [Fact],
    pub invalid: &'static [usize],
    pub serves: Served,
    pub life: Option<(u64, usize)>,
    pub alive: &'static [(&'static str, u64)],
    pub dead: &'static [(&'static str, u64, usize)],
    pub register: &'static [(&'static str, u64, usize, &'static str)],
    pub superseded: &'static [(&'static str, Option<(u64, usize)>)],
    pub late: &'static [(&'static str, u64, bool)],
}

